const re=/amethyst|dragon|golem|aspirant|anchored|vessel|raven/i;
return {world: game.world.id,
 scenes: game.scenes.filter(s=>s.folder?.name==="Raven's Trail").map(s=>({id:s.id,name:s.name})),
 actors: game.actors.filter(a=>re.test(a.name)||re.test(a.folder?.name??"")).map(a=>({id:a.id,name:a.name,folder:a.folder?.name,cr:a.system.details?.cr,hp:a.system.attributes?.hp?.max,mod:a._stats?.modifiedTime?new Date(a._stats.modifiedTime).toISOString().slice(0,10):null}))};

const FP = foundry.applications.apps.FilePicker.implementation;
try { await FP.createDirectory("data", "tmp-sim"); } catch (e) {}
const up = async (name, obj) => { const f = new File([JSON.stringify(obj)], name, {type: "application/json"}); return (await FP.upload("data", "tmp-sim", f, {}, {notify: false}))?.path; };
const out = {};
for (const id of ["RNDTDBlFXxZ7Uc8i","IxcfWOvpcKID6bdn","pfCQRWnqsQjkZQnB"]) {
  const a = game.actors.get(id); const o = a.toObject();
  o._derived = {hp: a.system.attributes.hp, ac: a.system.attributes.ac.value, prof: a.system.attributes.prof, spell: {dc: a.system.attributes.spell?.dc, mod: a.system.attributes.spellmod}, abilities: Object.fromEntries(Object.entries(a.system.abilities).map(([k,v])=>[k,{value:v.value,mod:v.mod,save:v.save?.value ?? v.save}])), spells: a.system.spells, init: a.system.attributes.init?.total, movement: a.system.attributes.movement, traits: a.system.traits};
  out[a.name] = await up(`pc-${a.name.split(" ")[0].toLowerCase()}.json`, o);
}
const names = ["Stone Golem","Flesh Golem","Clay Golem","Death Knight Aspirant","Adult Brass Dragon","Adult White Dragon","Shadow Dragon","Dracolich","Wight","Wraith","Specter","Ghoul","Ghast","Skeleton","Zombie","Mummy","Young Red Dragon"];
for (const n of names) {
  const m = await game.pentaryn.rules.monster(n);
  if (!m?.uuid) { out[n] = "notfound"; continue; }
  const a = await fromUuid(m.uuid); const o = a.toObject();
  o._derived = {hp: a.system.attributes.hp, ac: a.system.attributes.ac.value, prof: a.system.attributes.prof, cr: a.system.details.cr, xp: a.system.details.xp?.value, abilities: Object.fromEntries(Object.entries(a.system.abilities).map(([k,v])=>[k,{value:v.value,mod:v.mod,save:v.save?.value ?? v.save}])), traits: a.system.traits, legact: a.system.resources?.legact, legres: a.system.resources?.legres};
  out[n] = await up(`mon-${n.toLowerCase().replace(/\s+/g,"-")}.json`, o);
}
return out;

const out=[];
for (const a of game.actors.filter(a=>a.flags?.pentaryn?.ravensTrail)) {
  out.push({id:a.id,name:a.name,folder:a.folder?.name,hp:a.system.attributes.hp.max,ac:a.system.attributes.ac.value,cr:a.system.details.cr,
   legact:a.system.resources?.legact, legres:a.system.resources?.legres,
   items:a.items.map(i=>({n:i.name,t:i.type,act:i.system.activities?.map(x=>`${x.type}:${x.activation?.type}${x.uses?.max?"/"+x.uses.max:""}${x.uses?.recovery?.[0]?.formula?"r"+x.uses.recovery[0].formula:""}`).join(",")}))});
}
const toks=game.scenes.contents.flatMap(s=>s.tokens.filter(t=>t.actor?.flags?.pentaryn?.ravensTrail).map(t=>({scene:s.name,name:t.name,actorLink:t.actorLink,delta:!!Object.keys(t.delta?._source?.system??{}).length})));
return {out,toks};

const pick=(aid,names)=>{const a=game.actors.get(aid);return names.map(n=>{const i=a.items.getName(n);return {n,id:i.id,uses:i.system.uses,acts:i.system.activities.map(x=>({id:x.id,type:x.type,name:x.name,act:x.activation,cons:x.consumption,uses:x.uses,save:x.save,dmg:x.damage?.parts?.map(p=>({n:p.number,d:p.denomination,b:p.bonus,t:[...p.types],c:p.custom})),incl:x.damage?.includeBase,onSave:x.damage?.onSave,tgt:x.target,attack:x.attack&&{bonus:x.attack.bonus,flat:x.attack.flat,ability:x.attack.ability}})),wdmg:i.system.damage?.base&&{n:i.system.damage.base.number,d:i.system.damage.base.denomination,t:[...i.system.damage.base.types]}}})};
return {dragon:pick("jIddZJP55wdYcw8A",["Fire Breath","Scorching Sands","Rend","Legendary Resistance","Multiattack"]),anc:pick("T5rR0AxO3kf2Y8er",["Hellfire Orb","Destructive Wave","Spellcasting"]),wr:pick("tTFoR9vXdupO6ccW",["Life Drain"]),
traits:game.actors.get("jIddZJP55wdYcw8A").system.traits.toObject?.() ?? game.actors.get("jIddZJP55wdYcw8A")._source.system.traits, dsys:{abil:game.actors.get("jIddZJP55wdYcw8A")._source.system.abilities, attr:game.actors.get("jIddZJP55wdYcw8A")._source.system.attributes.senses, det:game.actors.get("jIddZJP55wdYcw8A")._source.system.details}};

const a = game.actors.get("jIddZJP55wdYcw8A");
const rid = () => foundry.utils.randomID();
// 1. drop the brass kit
const drop = ["Sleep Breath","Spellcasting","Detect Magic","Minor Illusion","Shapechange","Speak with Animals","Detect Thoughts","Control Weather","Blazing Light","Pounce"];
await a.deleteEmbeddedDocuments("Item", a.items.filter(i => drop.includes(i.name)).map(i => i.id));
// 2. core numbers
await a.update({
  "system.abilities.str.value": 23, "system.abilities.str.proficient": 0,
  "system.abilities.dex.value": 12, "system.abilities.dex.proficient": 1,
  "system.abilities.con.value": 21, "system.abilities.con.proficient": 1,
  "system.abilities.int.value": 18, "system.abilities.int.proficient": 0,
  "system.abilities.wis.value": 15, "system.abilities.wis.proficient": 1,
  "system.abilities.cha.value": 19, "system.abilities.cha.proficient": 1,
  "system.attributes.hp.max": 300, "system.attributes.hp.value": 300, "system.attributes.hp.formula": "",
  "system.details.cr": 12, "system.details.alignment": "", 
  "system.traits.di.value": [], "system.traits.dr.value": [], "system.traits.ci.value": [],
  "system.resources.legres.max": 2, "system.resources.legres.value": 2, "system.resources.legres.spent": 0,
  "system.resources.legact.max": 3, "system.resources.legact.spent": 0,
  "system.resources.legact.label": "Legendary Action Uses: 3. Immediately after another creature's turn, the dragon can expend a use to take the following action. It regains all expended uses at the start of each of its turns.",
  "system.details.biography.value": "<p><strong>Raven's split-soul experiment.</strong> An old amethyst dragon Raven tore half the soul out of, against its will. Half alive, half not; the missing half is in the Shattered Amethyst Dragon Shard Caven carries. Pain and rage. Its violet glow matches the shard.</p><p><strong>Tested build (Raven's Trail sims, 2026-10-21, re-run 2026-11-05):</strong> reads about CR 14 (11,500 XP) by the numbers; under the High budget for three level-12 PCs. Every Rend goes at Caven. <strong>Same-day (not the first fight since a long rest): set HP to 250.</strong></p><p><strong>At the table:</strong> start the breath uncharged; let players see it recharge; announce the shard grab.</p>"
});
// 3. Rend: add the force/necrotic rider (the type is picked on the damage roll: force while Living, necrotic while Hollow)
const rend = a.items.getName("Rend"); const ra = rend.system.activities.contents[0];
const parts = ra.toObject().damage.parts; parts.push({custom:{enabled:false,formula:""},number:1,denomination:8,bonus:"",types:["force","necrotic"],scaling:{number:1},modifiers:[]});
await rend.update({[`system.activities.${ra.id}.damage.parts`]: parts,
  "system.description.value": "<p><em>Melee Attack Roll:</em> +10, reach 10 ft. <em>Hit:</em> 2d10 + 6 Slashing damage plus 1d8 Force damage while <strong>Living</strong> or 1d8 Necrotic damage while <strong>Hollow</strong> (pick the type on the damage roll).</p>"});
// 4. Sundered Breath (was Fire Breath): 60-ft cone, DC 17 DEX, 5d8 force + 5d8 necrotic, Recharge 5-6, starts uncharged
const fb = a.items.getName("Fire Breath"); const fa = fb.system.activities.contents[0];
await fb.update({ name: "Sundered Breath", "system.uses.spent": 1,
  [`system.activities.${fa.id}.target.template`]: {contiguous:false,units:"ft",type:"cone",size:"60",count:"",width:"",stationary:false},
  [`system.activities.${fa.id}.damage.parts`]: [
    {custom:{enabled:false,formula:""},number:5,denomination:8,bonus:"",types:["force"],scaling:{number:1},modifiers:[]},
    {custom:{enabled:false,formula:""},number:5,denomination:8,bonus:"",types:["necrotic"],scaling:{number:1},modifiers:[]}],
  "system.description.value": `<p><em>Dexterity Saving Throw:</em> DC [[lookup @save.dc.value activity=${fa.id}]], each creature in a 60-foot Cone.</p><p><em>Failure:</em> [[/damage average]] damage (half Force, half Necrotic).</p><p><em>Success:</em> Half damage.</p><p><em>Starts uncharged:</em> it is not ready at the start of the fight; roll the recharge from its first turn.</p>`});
// 5. Psionic Lash (was Scorching Sands): legendary, DC 15 WIS, 4d6 psychic, nothing on a success; on a failure no reactions
const ss = a.items.getName("Scorching Sands"); const sa = ss.system.activities.contents[0];
for (const e of ss.effects) await e.delete();
const [eff] = await ss.createEmbeddedDocuments("ActiveEffect", [{ name: "Reeling (no reactions)", img: "icons/magic/control/hypnosis-mesmerism-swirl.webp", transfer: false,
  duration: { turns: 1 }, description: "<p>Psionic Lash: can't take reactions until the start of its next turn.</p>", changes: [] }]);
await ss.update({ name: "Psionic Lash", img: "icons/magic/control/hypnosis-mesmerism-swirl.webp",
  [`system.activities.${sa.id}.damage.parts`]: [{custom:{enabled:false,formula:""},number:4,denomination:6,bonus:"",types:["psychic"],scaling:{number:1},modifiers:[]}],
  [`system.activities.${sa.id}.damage.onSave`]: "none",
  [`system.activities.${sa.id}.save`]: {ability:["wis"],dc:{calculation:"",formula:"15"},visible:true},
  [`system.activities.${sa.id}.effects`]: [{_id: eff.id, onSave: false}],
  [`system.activities.${sa.id}.duration`]: {units:"inst",concentration:false,override:false,expiry:null},
  "system.description.value": `<p><strong>Legendary Action (1).</strong> It answers the creature that just acted ("it hears you").</p><p><em>Wisdom Saving Throw:</em> DC 15, one creature it can see within 120 feet.</p><p><em>Failure:</em> [[/damage average]] damage, and the target can't take reactions until the start of its next turn (no Shield, Counterspell or Cosmic Omen).</p><p><em>Success:</em> No effect.</p>`});
// 6. Legendary Resistance 2/Day
await a.items.getName("Legendary Resistance").update({"system.uses.label": "2/Day"});
// 7. Multiattack text
await a.items.getName("Multiattack").update({"system.description.value": "<p>The dragon makes two Rend attacks. Both go at the creature carrying the shard (Caven).</p>"});
// 8. new features
const feats = [
 { name: "Soul Flicker", type: "feat", img: "icons/magic/life/heart-cross-strong-flame-purple-orange.webp",
   system: { type: { value: "monster" }, description: { value: "<p>At the <strong>end of each of its turns</strong> the dragon swaps between <strong>Living</strong> and <strong>Hollow</strong> (toggle the two effects on its sheet). Roll the starting state. The state the party sees is the state of its next turn.</p><ul><li><strong>Living</strong> (violet): resistant to Psychic damage; can be charmed or frightened; Living Heart works; Rend rider is Force.</li><li><strong>Hollow</strong> (ash): immune to Necrotic and Poison damage and to the Charmed, Frightened, Poisoned and Exhaustion conditions (any charm or fear ends when it turns Hollow); no Living Heart; Rend rider is Necrotic.</li></ul>" } },
   effects: [
    { name: "Soul Flicker: Living", img: "icons/magic/life/heart-glowing-red.webp", transfer: true, disabled: false,
      changes: [{ key: "system.traits.dr.value", mode: 2, value: "psychic" }] },
    { name: "Soul Flicker: Hollow", img: "icons/magic/death/skull-energy-light-purple.webp", transfer: true, disabled: true,
      changes: [{ key: "system.traits.di.value", mode: 2, value: "necrotic" }, { key: "system.traits.di.value", mode: 2, value: "poison" },
                { key: "system.traits.ci.value", mode: 2, value: "charmed" }, { key: "system.traits.ci.value", mode: 2, value: "frightened" },
                { key: "system.traits.ci.value", mode: 2, value: "poisoned" }, { key: "system.traits.ci.value", mode: 2, value: "exhaustion" }] } ] },
 { name: "Living Heart", type: "feat", img: "icons/magic/life/heart-glowing-red.webp",
   system: { type: { value: "monster" }, description: { value: "<p>While <strong>Living</strong>, the dragon regains 10 Hit Points at the start of its turn, unless it took Radiant damage since the start of its last turn. No regeneration while Hollow.</p>" },
     activities: { [rid()]: { type: "heal", name: "Regain 10 HP", sort: 0, activation: { type: "special", condition: "Start of its turn, Living, no Radiant damage since its last turn" },
       range: { units: "self" }, target: { affects: { type: "self" } },
       healing: { custom: { enabled: true, formula: "10" }, number: null, denomination: null, bonus: "", types: ["healing"], scaling: { number: 1 } } } } } },
 { name: "Soul Rupture", type: "feat", img: "icons/magic/sonic/scream-wail-shout-teal.webp",
   system: { type: { value: "monster" }, uses: { max: "1", spent: 0, recovery: [{ period: "lr", type: "recoverAll" }] },
     description: { value: "<p>The first time the dragon drops to half its Hit Points or fewer (150), at the start of its next turn it lets out a <strong>Shard Wail</strong> (\"You carry my piece!\"), and its next flicker is forced Hollow.</p><p><em>Wisdom Saving Throw:</em> DC 15, every conscious creature on the party's side, summons included (creatures at 0 HP are skipped). <em>Failure:</em> 3d6 Psychic damage. <em>Success:</em> Half damage.</p>" },
     activities: { [rid()]: { type: "save", name: "Shard Wail", sort: 0, activation: { type: "special", condition: "Start of its turn after first dropping to half HP" },
       consumption: { targets: [{ type: "itemUses", value: "1", target: "", scaling: {} }] },
       range: { units: "self" }, target: { affects: { type: "enemy", special: "Every conscious creature on the party's side" } },
       save: { ability: ["wis"], dc: { calculation: "", formula: "15" } },
       damage: { onSave: "half", parts: [{ custom: { enabled: false, formula: "" }, number: 3, denomination: 6, bonus: "", types: ["psychic"], scaling: { number: 1 } }] } } } } },
 { name: "You Carry My Piece", type: "feat", img: "icons/commodities/gems/gem-rough-cushion-purple.webp",
   system: { type: { value: "monster" }, description: { value: "<p>If Caven has lain at 0 Hit Points through a full round (down at the end of the dragon's last turn and at the start of this one), one Rend per turn (50% chance) claws at the shard on his body: an automatic critical hit at 5 ft, which is two failed death saves. <strong>Announce it</strong> (\"it claws at the shard on his body\") so the party knows to pick him up. This is the only finishing blow; otherwise it does not attack downed creatures.</p>" } } }
];
await a.deleteEmbeddedDocuments("Item", a.items.filter(i => feats.some(f => f.name === i.name)).map(i => i.id));
await a.createEmbeddedDocuments("Item", feats);
a.reset();
