const out = {};
for (const id of ["5Gx5U3UI6RPYZwnU", "4FNFb4CCWVg2j2ol"]) {
  const s = game.scenes.get(id);
  const oldX = s.dimensions.sceneX, oldY = s.dimensions.sceneY, oldG = s.grid.size, oldW = s.width;
  if (oldG === 50 && s.width === 2500) { out[id] = "already 2500/50"; continue; }
  const before = s.tokens.map(t => ({ id: t.id, name: t.name, x: t._source.x, y: t._source.y }));
  await s.update({ width: 2500, height: 2500, "grid.size": 50 });
  const nX = s.dimensions.sceneX, nY = s.dimensions.sceneY, k = 2500 / oldW;
  const updates = before.map(t => {
    const cx = (t.x - oldX + oldG / 2) * k, cy = (t.y - oldY + oldG / 2) * k;   // centre of the old square, new pixels
    return { _id: t.id, x: nX + Math.floor(cx / 50) * 50, y: nY + Math.floor(cy / 50) * 50 };
  });
  // resolve collisions: bump east one square if taken
  const taken = new Set();
  for (const u of updates) { while (taken.has(`${u.x},${u.y}`)) u.x += 50; taken.add(`${u.x},${u.y}`); }
  await s.updateEmbeddedDocuments("Token", updates, { animate: false });
  out[id] = { oldOrigin: [oldX, oldY], newOrigin: [nX, nY], grid: s.grid.size, width: s.width, moved: s.tokens.map(t => ({ name: t.name.slice(0, 18), col: (t._source.x - nX) / 50, row: (t._source.y - nY) / 50 })) };
}
return out;

